namespace AutoCollider
{
    /// <summary>What happens to existing colliders when generating.</summary>
    public enum ReplaceMode
    {
        /// <summary>Replace colliders previously generated by Auto Collider (locked ones are kept). User colliders are untouched.</summary>
        ReplaceGenerated = 0,
        /// <summary>Keep everything and add new colliders.</summary>
        Append = 1,
        /// <summary>Remove every collider in the target hierarchy (except locked entries), including user-made ones.</summary>
        ReplaceAll = 2,
    }
}
